write(storyFile,[{id:`st_${id}_samlingen_som_matte_bygges_opp_igjen`,quality_profile:"episode_v1",type:"turning_point",title:"Samlingen som måtte bygges opp igjen",year:1970,place_id:id,summary:"Da store deler av skolemuseets gjenstandssamling ble kjørt bort i 1970, reddet frivillige noe; senere innsamlings- og restaureringsarbeid gjorde en ny museumsåpning mulig i 2000.",story:"I 1970 måtte gjenstandsmuseet ut av lokalene på Møllergata skole. Omkring fjorten billass ble sendt til Grønmo for destruksjon. Det pedagogiske biblioteket var allerede overført, og mye av den materielle samlingen gikk tapt.\n\nFrivillige reddet noen få billass. Det som overlevde, gjorde ikke samlingen hel, men ga senere museumsarbeid konkrete rester å bygge videre fra. På 1990-tallet kartla og samlet ansatte og frivillige eldre pedagogisk materiale fra skoler og andre kilder.\n\nI 1998 og 1999 ble rommene i den gamle overlærerboligen satt i stand. Oslo Skolemuseum åpnet 23. mai 2000. Historien er derfor ikke en ubrutt arv: museet formidler skolehistorie gjennom en samling preget av tap, redningsvalg og ny kuratering.",episode:{actors:["frivillige","skoleetatens museumsarbeidere"],date:"1970–2000",action:"Frivillige reddet deler av samlingen, og senere aktører samlet materiale og restaurerte rom.",consequence:"Oslo Skolemuseum kunne åpne i 2000, men samlingens dokumenterte brudd forble en del av proveniensen."},sources:[{title:"Oslo Skolemuseum – museets historie",url:urls.museumHistory},{title:"Oslo Skolemuseum – vår samling",url:urls.collection}],tags:["skolehistorie","museum","bevaring","proveniens"],related_people:[],related_places:[],next_scenes:[],score:{narrative:3,historical:3,source:4,play_value:3,originality:3,total:16},arc:{start:"Samlingen blir fjernet og mye skal ødelegges.",middle:"Frivillige redder rester, og nye aktører bygger opp samlingen.",end:"Restaurerte rom og en ny samling åpner som Oslo Skolemuseum i 2000."}}]);
